	/* string does not fit into name_buf */
	zassert_equal(ret, -EINVAL, "Decoding has to fail");
>>>>>>>> REPLACE
	/* string does not fit into name_buf */
	zassert_equal(ret, -ENOMEM, "Decoding has to fail");
>>>>>>>> REPLACE

